func (r *mutationResolver) VendorUpload(ctx context.Context, files []*graphql.Upload, input model.ProductInput) (*model.Product, error) {
	// Generate a shorter, simpler bucket name
	timestamp := time.Now().UnixNano() / 1000000 // milliseconds
	simpleName := strings.ToLower(strings.ReplaceAll(input.Name, " ", "-"))
	simpleName = regexp.MustCompile(`[^a-z0-9-]`).ReplaceAllString(simpleName, "")
	bucketName := fmt.Sprintf("v-%s-%d", simpleName[:helper.MinInt(len(simpleName), 10)], timestamp)

	log.Printf("Initial bucket name: %s", bucketName)

	// Ensure the bucket exists in MinIO
	if err := helper.CreateBucketInMinio(ctx, r.MinIOClient, bucketName); err != nil {
		return nil, err
	}

	var productURLs []string

	// Upload each file and store the URL
	for _, file := range files {
		fileURL, err := helper.UploadFileToMinio(ctx, r.MinIOClient, bucketName, "product", file)
		if err != nil {
			return nil, fmt.Errorf("failed to upload file %s: %v", file.Filename, err)
		}
		productURLs = append(productURLs, fileURL)
	}

	var categories []string
	for _, catptr := range input.Categories {
		if catptr != nil {
			categories = append(categories, *catptr)
		}
	}

	// Create a new product with the provided details
	product := model.Product{
		Name:       &input.Name,
		Price:      &input.Price,
		State:      &input.State,
		ImageUrls:  productURLs,
		Categories: categories,
	}
	// Check if VendorID is not nil and add it to the product
	if input.VendorID != nil {
		product.VendorID = input.VendorID
	}
	// Save the product to the database
	if err := r.DB.Create(&product).Error; err != nil {
		return nil, fmt.Errorf("failed to save product: %v", err)
	}

	return &product, nil
}

