// GetAllProductsByAdmin is the resolver for the getAllProductsByAdmin field.
func (r *queryResolver) GetAllProductsByAdmin(ctx context.Context) ([]*model.ProductInfor, error) {
	// Get all products
	var products []*model.Product
	if err := r.DB.Order("created_at DESC").Find(&products).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch products: %v", err)
	}

	// Create a map to count the number of items sold for each product
	productSoldCounts := make(map[string]int32)

	// Get all orders with their items
	var orders []*model.Order
	if err := r.DB.Preload("Items").Find(&orders).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch orders: %v", err)
	}

	// Count sold items for each product
	for _, order := range orders {
		for _, item := range order.Items {
			productSoldCounts[item.ProductID] += item.Quantity
		}
	}

	// Create the result array
	result := make([]*model.ProductInfor, 0, len(products))

	// Populate the result with products and their sold counts
	for _, product := range products {
		count := productSoldCounts[product.ID.String()] // Assuming product.ID is uuid.UUID
		info := &model.ProductInfor{
			Product:       product,
			ItemSoldCount: &count,
		}
		result = append(result, info)
	}

	return result, nil
}

