// GetAllOrderItemsByProductID is the resolver for the getAllOrderItemsByProductId field.
func (r *queryResolver) GetAllOrderItemsByProductID(ctx context.Context, orderID string) (*model.CartItemOrder, error) {
	// Parse the order ID
	parsedOrderID, err := uuid.Parse(orderID)
	if err != nil {
		return nil, fmt.Errorf("invalid order ID: %w", err)
	}

	// Fetch the order details
	var order model.Order
	if err := r.DB.Where("id = ?", parsedOrderID).First(&order).Error; err != nil {
		if err == gorm.ErrRecordNotFound {
			return nil, fmt.Errorf("order not found with ID: %s", orderID)
		}
		return nil, fmt.Errorf("failed to fetch order: %w", err)
	}

	// Fetch all cart items for this order
	var cartItems []model.CartItem
	if err := r.DB.Where("order_id = ?", orderID).Find(&cartItems).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch cart items: %w", err)
	}

	// Create a map to group products by cart item
	productInfos := make([]*model.OrderproductInfor, 0)

	// Process each cart item
	for _, item := range cartItems {
		// Fetch product for this cart item
		var product model.Product
		if err := r.DB.Where("id = ?", item.ProductID).First(&product).Error; err != nil {
			if err == gorm.ErrRecordNotFound {
				continue // Skip if product not found
			}
			return nil, fmt.Errorf("failed to fetch product: %w", err)
		}

		// Create product info entry
		productInfo := &model.OrderproductInfor{
			Product:  []*model.Product{&product},
			Quantity: int32(item.Quantity),
		}

		productInfos = append(productInfos, productInfo)
	}

	// Construct the response
	// result := &model.CartItemOrder{
	// 	OrderID:         orderID,
	// 	ProductInfor:    productInfos,
	// 	CustomerNumber:  order.CustomerNumber,
	// 	DeliveryAddress: order.DeliveryAddress,
	// }

	result := &model.CartItemOrder{
		OrderID:               orderID,
		ProductInfor:          productInfos,
		CustomerNumber:        order.CustomerNumber,
		DeliveryAddress:       order.DeliveryAddress,
		Status:                order.Status,                // Added Status field
		EstimatedDeliveryDate: order.EstimatedDeliveryDate, // Added EstimatedDeliveryDate field
		CreatedAt:             order.CreatedAt,             // Added CreatedAt field
	}

	return result, nil
}

// GetAllOrderItemsByProductIDDelivery is the resolver for the getAllOrderItemsByProductIdDelivery field.
func (r *queryResolver) GetAllOrderItemsByProductIDDelivery(ctx context.Context) ([]*model.CartItemOrder, error) {
	if err := middleware.RequireAuth(ctx); err != nil {
		return nil, err
	}

	var orders []*model.Order
	aDayAgo := time.Now().AddDate(0, 0, -1)

	// Fetch all orders with their items and related products
	if err := r.DB.Preload("Items").
		Where("status = ? AND created_at >= ?", "PENDING", aDayAgo).Order("created_at DESC").Find(&orders).Error; err != nil {

		return nil, fmt.Errorf("failed to fetch orders: %w", err)
	}

	// Create a map to store product data for each ProductID
	productMap := make(map[string]*model.Product)

	// Collect all unique ProductIDs from orders
	var productIDs []string
	for _, order := range orders {
		for _, item := range order.Items {
			if _, exists := productMap[item.ProductID]; !exists {
				productIDs = append(productIDs, item.ProductID)
			}
		}
	}

	// Fetch all products in one query
	var products []*model.Product
	if err := r.DB.Where("id IN ?", productIDs).Find(&products).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch products: %w", err)
	}

	// Build product map
	for _, product := range products {
		productMap[product.ID.String()] = product
	}

	// Map to store orders by delivery address
	addressOrderMap := make(map[string]*model.CartItemOrder)

	// Process each order
	for _, order := range orders {
		// Group products and quantities for this order
		productInfos := make([]*model.OrderproductInfor, 0)

		for _, item := range order.Items {
			if product, exists := productMap[item.ProductID]; exists {
				productInfo := &model.OrderproductInfor{
					Product:  []*model.Product{product},
					Quantity: item.Quantity,
				}
				productInfos = append(productInfos, productInfo)
			}
		}

		// Create or update CartItemOrder for this delivery address
		if cartOrder, exists := addressOrderMap[order.DeliveryAddress]; exists {
			// Merge product information
			for _, newInfo := range productInfos {
				merged := false
				for _, existingInfo := range cartOrder.ProductInfor {
					if existingInfo.Product[0].ID == newInfo.Product[0].ID {
						existingInfo.Quantity += newInfo.Quantity
						merged = true
						break
					}
				}
				if !merged {
					cartOrder.ProductInfor = append(cartOrder.ProductInfor, newInfo)
				}
			}
		} else {
			// Create new CartItemOrder for this address
			addressOrderMap[order.DeliveryAddress] = &model.CartItemOrder{
				OrderID:               order.ID.String(),
				ProductInfor:          productInfos,
				CustomerNumber:        order.CustomerNumber,
				DeliveryAddress:       order.DeliveryAddress,
				Status:                order.Status,
				EstimatedDeliveryDate: order.EstimatedDeliveryDate,
				CreatedAt:             order.CreatedAt,
			}
		}
	}

	// Convert map to slice
	result := make([]*model.CartItemOrder, 0, len(addressOrderMap))
	for _, order := range addressOrderMap {
		result = append(result, order)
	}

	// // Sort by delivery address
	// sort.Slice(result, func(i, j int) bool {
	// 	return result[i].DeliveryAddress < result[j].DeliveryAddress
	// })

	return result, nil
}

// UseGetordertracking is the resolver for the useGetordertracking field.
func (r *queryResolver) UseGetordertracking(ctx context.Context, orderID []*string) ([]*model.CartItemOrder, error) {
	log.Println("orderIDorderIDorderID Order ID:", orderID)
	middleware.CleanupOrderTrackingCookie(ctx, r.DB)

	rq := middleware.GetRequest(ctx) // Retrieve request from context
	if rq == nil {
		return nil, fmt.Errorf("unable to access request")
	}

	// Collect all order IDs to process
	var orderIDs []string

	// First try to get order IDs from cookie (main source)
	cookieOrderID, err := middleware.GetOrderTrackingCookie(rq)
	if err == nil && len(cookieOrderID) > 0 {
		orderIDs = append(orderIDs, cookieOrderID...)
		log.Println("Using Order IDs from cookie:", cookieOrderID)
	} else {
		// Only use orderID parameter as fallback if cookie is not available
		if orderID != nil && len(orderID) > 0 {
			for _, id := range orderID {
				if id != nil && *id != "" {
					orderIDs = append(orderIDs, *id)
				}
			}
			log.Println("Using fallback Order IDs from parameter:", orderIDs)
		}
	}

	// Check if we have any order IDs to process
	if len(orderIDs) == 0 {
		return nil, fmt.Errorf("no tracking cookie found and no orderID provided")
	}

	// Fetch all orders
	var orders []*model.Order
	if err := r.DB.Where("id IN ?", orderIDs).Preload("Items").Find(&orders).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch orders: %v", err)
	}

	if len(orders) == 0 {
		return nil, fmt.Errorf("no orders found")
	}

	// Process each order and create response
	result := make([]*model.CartItemOrder, 0, len(orders))
	for _, order := range orders {
		// Fetch related cart items
		var cartItems []model.CartItem
		if err := r.DB.Where("order_id = ?", order.ID).Find(&cartItems).Error; err != nil {
			return nil, fmt.Errorf("failed to fetch cart items for order %s: %v", order.ID, err)
		}

		// Process cart items and fetch product info
		productInfos := make([]*model.OrderproductInfor, 0)
		for _, item := range cartItems {
			var product model.Product
			if err := r.DB.Where("id = ?", item.ProductID).First(&product).Error; err != nil {
				if errors.Is(err, gorm.ErrRecordNotFound) {
					continue // Skip missing products
				}
				return nil, fmt.Errorf("failed to fetch product: %v", err)
			}

			productInfo := &model.OrderproductInfor{
				Product:  []*model.Product{&product},
				Quantity: int32(item.Quantity),
			}
			productInfos = append(productInfos, productInfo)
		}

		// Create the cart item order
		cartItemOrder := &model.CartItemOrder{
			OrderID:               order.ID.String(),
			ProductInfor:          productInfos,
			CustomerNumber:        order.CustomerNumber,
			DeliveryAddress:       order.DeliveryAddress,
			Status:                order.Status,
			EstimatedDeliveryDate: order.EstimatedDeliveryDate,
			CreatedAt:             order.CreatedAt,
		}

		result = append(result, cartItemOrder)
	}

	return result, nil
}

// GetAllUserStats is the resolver for the getAllUserStats field.
func (r *queryResolver) GetAllUserStats(ctx context.Context) ([]*model.UserInfor, error) {
	var orders []*model.Order

	// Fetch all orders with their items, ordered by customer number and creation date
	if err := r.DB.Preload("Items").Order("customer_number, created_at").Find(&orders).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch orders: %v", err)
	}

	// Map to store user information
	userInfoMap := make(map[string]*model.UserInfor)

	// Process each order to build user information
	for _, order := range orders {
		info, exists := userInfoMap[order.CustomerNumber]

		// Calculate total items in this order
		var orderItemsCount int32
		for _, item := range order.Items {
			orderItemsCount += item.Quantity
		}

		if !exists {
			// Create new info for this customer
			info = &model.UserInfor{
				CustomerNumber:    order.CustomerNumber,
				DeliveryAddresses: []string{order.DeliveryAddress},
				TotalOrders:       1,
				TotalitemsOrdered: orderItemsCount,
				FirstlastOrderDate: fmt.Sprintf("%s / %s",
					order.CreatedAt.Format("2006-01-02"),
					order.CreatedAt.Format("2006-01-02")),
			}
			userInfoMap[order.CustomerNumber] = info
		} else {
			// Update existing info
			info.TotalOrders++
			info.TotalitemsOrdered += orderItemsCount

			// Update the last order date in the combined string
			dates := strings.Split(info.FirstlastOrderDate, " / ")
			if len(dates) > 0 {
				info.FirstlastOrderDate = fmt.Sprintf("%s / %s",
					dates[0],
					order.CreatedAt.Format("2006-01-02"))
			}

			// Check if this address is already recorded
			addressExists := false
			for _, addr := range info.DeliveryAddresses {
				if addr == order.DeliveryAddress {
					addressExists = true
					break
				}
			}
			if !addressExists {
				info.DeliveryAddresses = append(info.DeliveryAddresses, order.DeliveryAddress)
			}
		}
	}

	// Convert map to slice
	result := make([]*model.UserInfor, 0, len(userInfoMap))
	for _, info := range userInfoMap {
		result = append(result, info)
	}

	// Sort by customer number
	sort.Slice(result, func(i, j int) bool {
		return result[i].CustomerNumber < result[j].CustomerNumber
	})

	return result, nil
}

// GetOrderChat is the resolver for the getOrderChat field.
func (r *queryResolver) GetOrderChat(ctx context.Context, orderID *string) (*model.OrderChat, error) {
	middleware.CleanupOrderTrackingCookie(ctx, r.DB)

	// Parse the order ID
	parsedOrderID, err := uuid.Parse(*orderID)
	if err != nil {
		return nil, fmt.Errorf("invalid order ID: %v", err)
	}

	// Verify that the order exists
	var order model.Order
	if err := r.DB.Where("id = ?", parsedOrderID).First(&order).Error; err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return nil, fmt.Errorf("order not found with ID: %s", parsedOrderID)
		}
		return nil, fmt.Errorf("failed to fetch order: %v", err)
	}

	// Fetch all chat messages for this order, ordered by timestamp
	var messages []*model.ChatMessage
	if err := r.DB.Where("order_id = ?", orderID).
		Order("created_at ASC").
		Find(&messages).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch chat messages: %v", err)
	}

	// Create the order chat response
	orderChat := &model.OrderChat{
		OrderID:  *orderID,
		Messages: messages,
	}

	return orderChat, nil
}

// GetAllChatMessageByNumber is the resolver for the getAllChatMessageByNumber field.
func (r *queryResolver) GetAllChatMessageByNumber(ctx context.Context, customerNumber string) ([]*model.ChatMessage, error) {
	// First get all orders for this customer number
	var orders []*model.Order
	if err := r.DB.Where("customer_number = ?", customerNumber).
		Order("created_at DESC").
		Find(&orders).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch orders: %v", err)
	}

	if len(orders) == 0 {
		return nil, fmt.Errorf("no orders found for customer number: %s", customerNumber)
	}

	// Collect all order IDs
	var orderIDs []string
	for _, order := range orders {
		orderIDs = append(orderIDs, order.ID.String())
	}

	// Fetch all chat messages for these orders
	var messages []*model.ChatMessage
	if err := r.DB.Where("order_id IN ?", orderIDs).
		Order("created_at ASC").
		Find(&messages).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch chat messages: %v", err)
	}

	return messages, nil
}

// GetAllRequestItems is the resolver for the getAllRequestItems field.
func (r *queryResolver) GetAllRequestItems(ctx context.Context) ([]*model.RequestItem, error) {
	var requestItems []*model.RequestItem

	// Fetch all request items, ordered by creation date (newest first)
	if err := r.DB.Order("created_at DESC").Find(&requestItems).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch request items: %v", err)
	}

	return requestItems, nil
}

// GetAllCategoryBox is the resolver for the getAllCategoryBox field.
func (r *queryResolver) GetAllCategoryBox(ctx context.Context, query *string) ([]*model.ViewcategoryBox, error) {
	var categoryBoxes []*model.CategoryBox
	var products []*model.Product

	// Apply search if query is provided
	if query != nil && *query != "" {
		searchedCategories, err := helper.ExecuteCategorySearchQuery(r.DB, *query)
		if err != nil {
			return nil, err
		}

		if len(searchedCategories) > 0 {
			categoryBoxes = searchedCategories
		} else {
			// No categories found, search in products
			searchedProducts, err := helper.ExecuteSearchQuery(r.DB, *query)
			if err != nil {
				return nil, err
			}

			if len(searchedProducts) > 0 {
				products = searchedProducts

				// Get all categories that contain any of these products
				var productIDs []string
				for _, product := range products {
					productIDs = append(productIDs, product.ID.String())
				}

				if err := r.DB.Where("items_ids && ?", pq.Array(productIDs)).Find(&categoryBoxes).Error; err != nil {
					return nil, err
				}
			}
		}
	} else {
		// Fetch all categories if no search query
		if err := r.DB.Find(&categoryBoxes).Error; err != nil {
			return nil, err
		}
	}

	var result []*model.ViewcategoryBox
	for _, categoryBox := range categoryBoxes {
		var categoryProducts []*model.Product
		if len(categoryBox.ItemsIds) > 0 {
			if err := r.DB.Where("id = ANY(?)", pq.Array(categoryBox.ItemsIds)).Find(&categoryProducts).Error; err != nil {
				return nil, err
			}
		}

		viewCategoryBox := &model.ViewcategoryBox{
			CategoryBox: categoryBox,
			Products:    categoryProducts,
		}
		result = append(result, viewCategoryBox)
	}

	return result, nil
}

// GetNewAddedCategoryBox is the resolver for the getNewAddedCategoryBox field.
func (r *queryResolver) GetNewAddedCategoryBox(ctx context.Context) ([]*model.CategoryBox, error) {
	var categoryBoxes []*model.CategoryBox
	addedDayAgo := time.Now().AddDate(0, 0, -1)

	if err := r.DB.Where("created_at >= ?", addedDayAgo).Order("created_at DESC").Find(&categoryBoxes).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch products: %v", err)
	}
	return categoryBoxes, nil
}

// GetCategoryBox is the resolver for the getCategoryBox field.
func (r *queryResolver) GetCategoryBox(ctx context.Context, categoryID string) (*model.CategoryBox, error) {
	var categoryBox model.CategoryBox
	if err := r.DB.First(&categoryBox, "id = ?", categoryID).Error; err != nil {
		return nil, err
	}
	return &categoryBox, nil
}

// GetProductsByCategory is the resolver for the getProductsByCategory field.
func (r *queryResolver) GetProductsByCategory(ctx context.Context, categoryID string) ([]*model.Product, error) {
	var categoryBox model.CategoryBox
	if err := r.DB.First(&categoryBox, "id = ?", categoryID).Error; err != nil {
		return nil, err
	}

	var products []*model.Product
	if len(categoryBox.ItemsIds) > 0 {
		if err := r.DB.Where("id IN (?)", categoryBox.ItemsIds).Find(&products).Error; err != nil {
			return nil, err
		}
	}

	return products, nil
}

